// Threshold (KB): file dengan ukuran <= nilai ini tidak dikompresi.
// Diatur lewat atribut data-threshold; jika tidak ada dipakai DEFAULT_THRESHOLD_KB.
const DEFAULT_THRESHOLD_KB = 100;

function uploadGambarSingle() {
    document.querySelectorAll('.unggah input[type="file"]').forEach((input) => {
        const unggah  = input.closest(".unggah");
        if (!unggah) return;

        const spinner = unggah.querySelector(".loadingSpinner");
        const preview = unggah.querySelector(`#preview_${input.id}`);
        const info    = unggah.querySelector(`#info_${input.id}`);
        if (!preview) return;

        input.addEventListener("change", function (e) {
            const file = e.target.files[0];
            if (!file || !file.type.match(/image.*/)) return;

            // Tampilkan loading spinner selama membaca / mengompres gambar
            if (spinner) spinner.style.display = "inline-block";

            const reader = new FileReader();
            reader.onload = function (event) {
                const img = new Image();
                img.onload = function () {
                    const maxWidth = unggah.dataset.maxWidth ? parseInt(unggah.dataset.maxWidth) : img.width;
                    const quality  = unggah.dataset.quality ? parseFloat(unggah.dataset.quality) : 0.9;
                    // data-ukuran = batas maksimal ukuran (KB), bukan threshold kompresi
                    const ukuranKB = unggah.dataset.ukuran ? parseInt(unggah.dataset.ukuran) : 2048;
                    // data-threshold = batas agar file tidak perlu dikompresi
                    const thresholdKB = unggah.dataset.threshold ? parseInt(unggah.dataset.threshold) : DEFAULT_THRESHOLD_KB;

                    // Jika ukuran file asli sudah kecil, langsung preview tanpa kompresi
                    if (file.size <= 1024 * thresholdKB) {
                        if (spinner) spinner.style.display = "none";
                        preview.src = URL.createObjectURL(file);
                        if (info) info.innerHTML = `<small>Dimensi asli: ${img.width}x${img.height} px<br>Ukuran asli: ${(file.size / 1024).toFixed(1)} KB</small>`;
                        return;
                    }

                    // Jalankan proses kompresi Pica.js
                    setTimeout(() => {
                        const canvas = document.createElement("canvas");
                        const scale  = Math.min(maxWidth / img.width, 1);
                        canvas.width  = img.width * scale;
                        canvas.height = img.height * scale;

                        // Menggunakan pica.min.js
                        pica().resize(img, canvas)
                            .then(() => pica().toBlob(canvas, "image/jpeg", quality))
                            .then(blob => {
                                if (spinner) spinner.style.display = "none";
                                preview.src = URL.createObjectURL(blob);

                                const width  = canvas.width;
                                const height = canvas.height;
                                const sizeKB = (blob.size / 1024).toFixed(1);
                                if (info) info.innerHTML = `<small>Dimensi gambar: ${width}x${height} px<br>Ukuran setelah proses: ${sizeKB} KB</small>`;

                                if (blob.size > 1024 * ukuranKB) {
                                    console.warn(`Ukuran hasil kompresi (${sizeKB} KB) masih melebihi batas ${ukuranKB} KB.`);
                                }

                                // Timpa file di input dengan file hasil kompresi
                                const newFile = new File([blob], file.name, { type: blob.type });
                                const dt      = new DataTransfer();
                                dt.items.add(newFile);
                                input.files = dt.files;
                            })
                            .catch((err) => {
                                if (spinner) spinner.style.display = "none";
                                console.error("Gagal kompresi gambar:", err);
                            });
                    }, 500);
                };
                img.onerror = function () {
                    if (spinner) spinner.style.display = "none";
                    console.error("Gagal membaca gambar untuk preview.");
                };
                img.src = event.target.result;
            };
            reader.readAsDataURL(file);
        });
    });
}

// Inisialisasi otomatis (script dimuat dengan defer, jadi DOM sudah siap)
document.addEventListener("DOMContentLoaded", uploadGambarSingle);

// Validasi ukuran file saat form upload gambar disubmit
document.querySelectorAll("form.form-upload-gambar").forEach((form) => {
    const input = form.querySelector('input[type="file"]'),
        unggah = input.closest(".unggah"),
        maxSizeKB = parseInt(unggah.dataset.ukuran) || 2048;
    form.addEventListener("submit", function (e) {
        const file = input.files[0];
        if (!file)
            return (
                e.preventDefault(),
                void Swal.fire("Validasi File", "Silakan upload file terlebih dahulu.", "warning")
            );
        file.size > 1024 * maxSizeKB &&
            (e.preventDefault(), Swal.fire("Validasi Ukuran", `Ukuran maksimal adalah ${maxSizeKB} KB.`, "error"));
    });
});